// The repository architecture record as the YAML the export writes (the
// contract "Repository architecture record and architecture file", "YAML
// form"): keys in the record's documented order, lists in the record's order,
// block scalars for multi-line strings, and a header comment. Pure and
// deterministic: the same record always gives the same text.

export const YAML_HEADER =
  "# Generated by the harness from the repository architecture. Edit it in the harness; changes here are not read back yet.";

/** Key order per kind of object; a key that is not listed follows the listed ones, in the record's order. */
const ORDER = {
  "": ["version", "repository", "pattern", "instructions", "tools", "sandboxes", "orchestration", "layers", "unlayered", "rules"],
  instructions: ["path", "kind", "applies_to", "loaded", "note"],
  tools: ["name", "kind", "used_by", "writes", "usage"],
  sandboxes: ["name", "runs", "can_reach", "cannot_reach", "used_by"],
  orchestration: ["routing", "handoffs"],
  "orchestration.routing": ["agent", "model", "note"],
  "orchestration.handoffs": ["from", "to", "when"],
  layers: ["name", "match", "bounded_context", "purpose", "access"],
  "layers.match": ["folder", "regex"],
  "layers.access": ["default", "agents"],
  unlayered: ["default", "agents"],
  rules: ["id", "kind", "at", "command", "paths", "tools", "timeout_seconds", "mode", "message", "agents"],
};

const isObject = (v) => v !== null && typeof v === "object" && !Array.isArray(v);

/** @param {any} record @returns {string} */
export function recordToYaml(record) {
  const lines = [YAML_HEADER];
  emitMap(record ?? {}, "", 0, lines);
  return lines.join("\n") + "\n";
}

/** The context of the objects under `key`, which picks their key order. */
const childContext = (ctx, key) => (ctx === "" ? key : `${ctx}.${key}`);

function orderedKeys(obj, ctx) {
  const known = ORDER[ctx] ?? [];
  const keys = Object.keys(obj).filter((k) => obj[k] !== undefined);
  return [...known.filter((k) => keys.includes(k)), ...keys.filter((k) => !known.includes(k))];
}

function emitMap(obj, ctx, indent, lines, firstPrefix = "") {
  const keys = orderedKeys(obj, ctx);
  keys.forEach((key, i) => {
    const pad = i === 0 && firstPrefix ? firstPrefix : " ".repeat(indent);
    emitEntry(`${pad}${scalar(key, false)}:`, obj[key], childContext(ctx, key), indent, lines);
  });
}

function emitEntry(head, value, ctx, indent, lines) {
  if (Array.isArray(value)) {
    if (value.length === 0) lines.push(`${head} []`);
    else if (value.every((v) => !isObject(v) && !Array.isArray(v) && !isMulti(v))) {
      lines.push(`${head} [${value.map((v) => scalar(v, true)).join(", ")}]`);
    } else {
      lines.push(head);
      for (const item of value) emitItem(item, ctx, indent + 2, lines);
    }
  } else if (isObject(value)) {
    if (Object.keys(value).length === 0) lines.push(`${head} {}`);
    else {
      lines.push(head);
      emitMap(value, ctx, indent + 2, lines);
    }
  } else if (isMulti(value)) {
    lines.push(`${head} ${blockHeader(value)}`);
    for (const l of value.replace(/\n+$/, "").split("\n")) lines.push(l === "" ? "" : `${" ".repeat(indent + 2)}${l}`);
  } else {
    lines.push(`${head} ${scalar(value, false)}`);
  }
}

function emitItem(item, ctx, indent, lines) {
  const pad = " ".repeat(indent);
  if (isObject(item) && Object.keys(item).length > 0) emitMap(item, ctx, indent + 2, lines, `${pad}- `);
  else if (Array.isArray(item) || isObject(item)) lines.push(`${pad}- ${Array.isArray(item) ? "[]" : "{}"}`);
  else if (isMulti(item)) {
    lines.push(`${pad}- ${blockHeader(item)}`);
    for (const l of item.replace(/\n+$/, "").split("\n")) lines.push(l === "" ? "" : `${pad}  ${l}`);
  } else lines.push(`${pad}- ${scalar(item, false)}`);
}

/** A multi-line string that a block scalar can carry. */
const isMulti = (v) => typeof v === "string" && v.includes("\n") && !/^[ \t]/.test(v) && !/\r/.test(v);

function blockHeader(s) {
  if (!s.endsWith("\n")) return "|-";
  return s.endsWith("\n\n") ? "|+" : "|";
}

const RESERVED = /^(true|false|yes|no|on|off|null|~|y|n)$/i;
const NUMBER = /^[-+]?(\.\d|\d)[\d_.eE+:-]*$|^0[xob][0-9a-f]+$|^[-+]?\.(inf|nan)$/i;

/** One scalar: plain when it is safe, else single-quoted (double-quoted when it holds a line break). */
function scalar(v, inFlow) {
  if (v === null || v === undefined) return "null";
  if (typeof v === "boolean" || typeof v === "number") return String(v);
  const s = String(v);
  if (/[\n\r\t\u0000-\u001f]/.test(s)) return JSON.stringify(s);
  const flowUnsafe = inFlow && /[,[\]{}]/.test(s);
  const plain =
    s !== "" &&
    s === s.trim() &&
    !RESERVED.test(s) &&
    !NUMBER.test(s) &&
    !flowUnsafe &&
    !/^[-?:,[\]{}#&*!|>'"%@`^]/.test(s) &&
    !/: |:$| #/.test(s);
  return plain ? s : `'${s.replace(/'/g, "''")}'`;
}
